package com.retailops.orders.pricing;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvFileSource;

import com.retailops.orders.support.TestFixtures;
import com.retailops.schemas.CustomerTier;
import com.retailops.schemas.Region;

/**
 * Data generated by {@code scripts/generate_pricing_cases.py}, whose independent Python oracle
 * computes the expected amounts. Each row is priced by the real {@link PricingService}.
 */
class GeneratedPricingScenariosTest {

    private final PricingService service = TestFixtures.defaultPricingService();

    @ParameterizedTest(name = "{0}: {2}/{3} coupon={4} -> {5}")
    @CsvFileSource(resources = "/generated/pricing-scenarios.csv", numLinesToSkip = 1)
    void scenario(String id, String lines, CustomerTier tier, Region region, String coupon, String outcome,
            String subtotal, String bulkDiscount, String tierDiscount, String couponDiscount, String tax,
            String shipping, String total) {
        PricingRequest request = new PricingRequest(parseLines(lines), tier, region, parseCoupon(id, coupon),
                TestFixtures.PRICING_DATE);
        if (outcome.startsWith("REJECT:")) {
            CouponRejectionReason reason = CouponRejectionReason.valueOf(outcome.substring("REJECT:".length()));
            assertThatThrownBy(() -> service.quote(request))
                    .isInstanceOfSatisfying(CouponRejectedException.class,
                            ex -> assertThat(ex.getReason()).isEqualTo(reason));
            return;
        }
        PriceBreakdown b = service.quote(request);
        assertThat(b).isEqualTo(new PriceBreakdown(new BigDecimal(subtotal), new BigDecimal(bulkDiscount),
                new BigDecimal(tierDiscount), new BigDecimal(couponDiscount), new BigDecimal(tax),
                new BigDecimal(shipping), new BigDecimal(total)));
    }

    static List<PricedLine> parseLines(String spec) {
        return Arrays.stream(spec.split(";")).map(part -> {
            String[] f = part.split(":");
            return new PricedLine(f[0], Integer.parseInt(f[1]), new BigDecimal(f[2]));
        }).toList();
    }

    static Coupon parseCoupon(String id, String spec) {
        if ("NONE".equals(spec)) {
            return null;
        }
        String[] f = Arrays.copyOf(spec.split("\\|", -1), 6);
        return new Coupon("GEN" + id, CouponType.valueOf(f[0]), new BigDecimal(f[1]), decimalOrNull(f[2]),
                decimalOrNull(f[3]), dateOrNull(f[4]), dateOrNull(f[5]), true);
    }

    private static BigDecimal decimalOrNull(String s) {
        return s == null || s.isEmpty() ? null : new BigDecimal(s);
    }

    private static LocalDate dateOrNull(String s) {
        return s == null || s.isEmpty() ? null : LocalDate.parse(s);
    }
}
